fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let pal = [0x1b1b2f, 0x3d2c8d, 0x916bbf, 0xc996cc, 0xffd5cd, 0xff7b54];
    let m: i32 = if w < h { h } else { w };
    let mut s: i32 = m;
    let mut i: i32 = 0;
    while s > 0 {
        host::display::fill_rect(cx - s / 2, cy - s / 2, s, s, pal[(i + t / 10) % 6]);
        s = s - 28;
        i = i + 1;
    }
    host::display::present();
}
